const D = { energy: .6, scale: 1, density: .5, weather: .5, speed: 1, hue: 32, x: .5, y: .74, alpha: 1, style: 'granite', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const sand=(sty==='sandstone'), bas=(sty==='basalt'), lidar=(sty==='lidar'), ash=(sty==='ash');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), wx=cl(P.weather,0,1.4), act=P.act;
const cx=cl(P.x,.05,.95)*W, cy=cl(P.y,.3,1.0)*Hh;
const rx=u*.44*sc, ry=rx*.30;
const NST=Math.max(4,Math.round(5+dens*9));

S.bass=(S.bass||0)*.85+(A.bass||0)*.15;
const T=K.t*spd;
const glow=(.32+.78*en)*(.55+.5*K.intensity)+S.bass*.25;

// ---- the sun: a MONOTONIC drift + two incommensurate wobbles.
// The wobble amplitudes are deliberately held BELOW the linear term's 8s
// travel, so |la(t+8)-la(t)| has a hard floor (~0.20 rad) no matter when the
// motion gate samples. A wobble big enough to cancel the drift is exactly how
// a "clearly moving" piece reads STATIC 8s later — so it isn't allowed to.
let la=T*.048+.26*Math.sin(T*.047)+.10*Math.sin(T*.113);
let le=.34+.26*Math.sin(T*.019+1.2)+.08*Math.sin(T*.061);
if(act==='vigil'){ la=T*.018+.14*Math.sin(T*.029); le=.16+.07*Math.sin(T*.017); }
else if(act==='race'){ la=T*.095+.40*Math.sin(T*.071); }
le=cl(le,.07,.72);
const shLen=cl(1/Math.max(.10,le),1.2,9)*ry*.42;    // low sun -> long shadows

// ---- seeded ring plan -----------------------------------------------------
function plan(){
  const st=[];
  for(let i=0;i<NST;i++){
    const a=(i/NST)*TAU+(fr(i*3.7)-.5)*(TAU/NST)*.5;
    const dep=(Math.sin(a)+1)*.5;                    // 0 far (back of ring) .. 1 near
    const per=.42+.80*dep;                           // perspective
    const h=u*.30*sc*(.62+.52*fr(i*3.7+1))*per;
    const w=h*(.22+.20*fr(i*3.7+2));
    const fallen=fr(i*3.7+3)>(.80-wx*.16);
    const verts=[];
    const NV=9;
    for(let k=0;k<NV;k++){                            // an irregular weathered column
      const q=k/NV;
      const side=(k<NV/2)?-1:1;
      const t2=(k<NV/2)?(k/(NV/2)):(1-(k-NV/2)/(NV/2));
      const taper=.62+.38*(1-t2);
      const jag=(fr(i*3.7+10+k)-.5)*.34;
      verts.push({sx:side*w*.5*taper*(1+jag), sy:-h*t2});
    }
    st.push({ a:a, dep:dep, h:h, w:w, fallen:fallen, verts:verts,
      ori:fr(i*3.7+4)*TAU, lean:(fr(i*3.7+5)-.5)*.30, per:per });
  }
  st.sort((p,q)=>p.dep-q.dep);                        // far stones first
  return st;
}

const pkey=[sd,NST,Math.round(sc*40),Math.round(wx*6),Math.round(P.x*120),Math.round(P.y*120),W,Hh].join('|');
if(!S.plan||S.pk!==pkey){ S.plan=plan(); S.pk=pkey; }
const st=S.plan;

// ---- cached rock grain: one small tile, stretched under a compound clip ----
const gkey=[sty,sd,Math.round(H),Math.round(wx*6)].join('|');
if(!S.grain||S.gk!==gkey){
  const GN=220;
  const g=(S.grain&&S.grain.width===GN)?S.grain:createGraphics(GN,GN);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  // mottling: broad tonal blotches so the rock is never one flat value
  for(let k=0;k<180;k++){
    const bx2=fr(k*1.7)*GN, by2=fr(k*1.7+1)*GN, rr=GN*(.03+fr(k*1.7+2)*.14);
    g.fill(md(H+(fr(k*1.7+3)-.5)*24,360), sand?16:(bas?8:10), fr(k*1.7+4)>.5?68:16, 9);
    g.ellipse(bx2,by2,rr*2.2,rr*1.7);
  }
  // stipple: the tooth of the stone
  for(let k=0;k<2600;k++){
    const bx2=fr(k*2.3+7)*GN, by2=fr(k*2.3+8)*GN;
    const up=fr(k*2.3+9)>.5;
    g.fill(md(H+(fr(k*2.3+10)-.5)*30,360), sand?20:10, up?78:8, 12+fr(k*2.3+11)*16);
    g.rect(bx2,by2,GN*.004*(1+fr(k*2.3+12)*2),GN*.004*(1+fr(k*2.3+12)));
  }
  if(sand){ // bedding planes: sandstone is laid down in strata
    for(let k=0;k<26;k++){
      const yy=fr(k*5.1+3)*GN;
      g.fill(md(H-6,360),24,fr(k*5.1+4)>.5?62:12,14);
      g.rect(0,yy,GN,GN*(.004+fr(k*5.1+5)*.014));
    }
  }
  if(bas){ // columnar basalt: hexagonal fracture, vertical joints
    g.noFill();
    for(let k=0;k<20;k++){
      g.stroke(md(H+180,360),8,fr(k*7.3)>.5?58:4,18);
      g.strokeWeight(GN*.004);
      g.line(fr(k*7.3+1)*GN,0,fr(k*7.3+1)*GN+GN*.06,GN);
    }
    g.noStroke();
  }
  // lichen: the only living thing on the stone — rosettes, not a wash
  const NL=Math.round(wx*70);
  for(let k=0;k<NL;k++){
    const bx2=fr(k*3.1+40)*GN, by2=fr(k*3.1+41)*GN, rr=GN*(.008+fr(k*3.1+42)*.030);
    const lh=md(H+fr(k*3.1+43)*44+40,360);
    g.fill(lh,34+fr(k*3.1+44)*22,44+fr(k*3.1+45)*26,22);
    g.ellipse(bx2,by2,rr*2,rr*1.8);
    for(let q=0;q<6;q++){
      g.fill(lh,40,58,24);
      g.ellipse(bx2+Math.cos(q*1.05)*rr*.7,by2+Math.sin(q*1.05)*rr*.6,rr*.5,rr*.45);
    }
  }
  S.grain=g; S.gk=gkey;
}

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
const lightX=Math.cos(la), lightY=Math.sin(la);

// ---- cast shadows first: the ring is a sundial, and this is the hand -------
// they sweep a large area as the sun drifts — the piece's main motion
if(!ash){
  dc.globalCompositeOperation='source-over';
  noStroke();
  for(let i=0;i<st.length;i++){
    const s=st[i];
    if(lidar) break;
    const px=cx+Math.cos(s.a)*rx, py=cy+Math.sin(s.a)*ry;
    const len=shLen*(.5+.9*s.per)*(s.fallen?.4:1);
    const ex=px-lightX*len, ey=py-lightY*len*.34;
    const hw=s.w*.5*(.8+.5*le);
    fill(md(H+186,360),18,3,cl(26*(.4+.6*glow),0,34)*AL);
    beginShape();
    vertex(px-hw,py); vertex(px+hw,py);
    vertex(ex+hw*.5,ey); vertex(ex-hw*.5,ey);
    endShape(CLOSE);
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- the stones -----------------------------------------------------------
const bodies=[];
for(let i=0;i<st.length;i++){
  const s=st[i];
  const px=cx+Math.cos(s.a)*rx, py=cy+Math.sin(s.a)*ry;
  // how squarely this stone faces the sun — the whole ring lights in a slow wave
  const facing=Math.cos(la-s.ori);
  const litAmt=cl(.5+.5*facing,0,1);
  const haze=cl(.30+.70*s.dep,0,1);          // far side of the ring sits back in air

  push();
  translate(px,py);
  if(s.fallen){ rotate(Math.PI*.5*(s.lean>0?1:-1)*.92); translate(0,-s.w*.5); }
  else rotate(s.lean*.5);

  const path=[];
  for(const v of s.verts) path.push({x:v.sx,y:v.sy});
  // remember the silhouette in screen space so the grain can be clipped to it
  bodies.push({s:s,px:px,py:py,path:path,fallen:s.fallen,lean:s.lean});

  if(lidar){
    // an archaeological laser scan: the stone exists only as returns,
    // denser and hotter where the beam hits square
    noStroke();
    const step=Math.max(3,s.h*.055);
    for(let yy=-s.h;yy<=0;yy+=step){
      for(let xx=-s.w*.6;xx<=s.w*.6;xx+=step){
        let inside=false, n=path.length;
        for(let a2=0,b2=n-1;a2<n;b2=a2++){
          if(((path[a2].y>yy)!==(path[b2].y>yy))&&
             (xx<(path[b2].x-path[a2].x)*(yy-path[a2].y)/(path[b2].y-path[a2].y)+path[a2].x)) inside=!inside;
        }
        if(!inside) continue;
        const hgt=cl(-yy/Math.max(1,s.h),0,1);
        fill(md(H+40+240*hgt,360),72,cl(38+54*litAmt,10,98),cl((36+44*litAmt)*haze,0,92)*AL);
        circle(xx,yy,Math.max(1,step*.34));
      }
    }
  } else {
    // the mass: dark, and lit only as far as the sun reaches round the ring
    let bs,bb;
    if(ash){ bs=10; bb=3+7*litAmt; }
    else if(bas){ bs=8+6*litAmt; bb=(5+34*litAmt)*(.45+.65*haze); }
    else if(sand){ bs=22+10*litAmt; bb=(10+52*litAmt)*(.45+.65*haze); }
    else { bs=8+8*litAmt; bb=(7+44*litAmt)*(.45+.65*haze); }
    fill(md(H+(ash?186:0),360),cl(bs,0,50),cl(bb,2,92),96*AL);
    beginShape(); for(const v of path) vertex(v.x,v.y); endShape(CLOSE);

    // the sun rakes ACROSS the slab: a directional falloff, clipped to the
    // stone, sweeping side to side as the azimuth drifts round the ring
    if(!ash&&litAmt>.04){
      const side=Math.sign(Math.sin(la-s.ori))||1;
      dc.save();
      dc.beginPath();
      for(let k=0;k<path.length;k++){
        if(k===0) dc.moveTo(path[k].x,path[k].y); else dc.lineTo(path[k].x,path[k].y);
      }
      dc.closePath(); dc.clip();
      dc.globalCompositeOperation='lighter';
      const gx0=-side*s.w*.62, gx1=side*s.w*.62;
      const lgr=dc.createLinearGradient(gx0,0,gx1,0);
      const warm=sand?'255,214,150':(bas?'198,216,255':'255,236,206');
      const pk=(0.30+0.46*glow)*litAmt*AL*(.4+.7*haze);
      lgr.addColorStop(0,'rgba('+warm+','+pk.toFixed(3)+')');
      lgr.addColorStop(.45,'rgba('+warm+','+(pk*.34).toFixed(3)+')');
      lgr.addColorStop(1,'rgba('+warm+',0)');
      dc.fillStyle=lgr;
      dc.fillRect(-s.w,-s.h*1.05,s.w*2,s.h*1.15);
      dc.globalCompositeOperation='source-over';
      dc.restore();
    }
    // ambient occlusion where the stone meets the ground — it must sit, not float
    fill(md(H+186,360),16,2,cl(40*haze,0,44)*AL);
    ellipse(0,0,s.w*1.5,s.w*.34);
  }
  pop();
}

// ---- rock texture: one compound clip, one stretched grain tile ------------
if(!lidar&&!ash){
  dc.save();
  dc.beginPath();
  for(const b of bodies){
    const s=b.s;
    const rot=b.fallen?(Math.PI*.5*(b.lean>0?1:-1)*.92):(b.lean*.5);
    const ca=Math.cos(rot), sa2=Math.sin(rot);
    const oy=b.fallen?-s.w*.5:0;
    for(let k=0;k<b.path.length;k++){
      const v=b.path[k];
      const vy=v.y+oy;
      const X=b.px+v.x*ca-vy*sa2, Y=b.py+v.x*sa2+vy*ca;
      if(k===0) dc.moveTo(X,Y); else dc.lineTo(X,Y);
    }
    dc.closePath();
  }
  dc.clip();
  const bw=rx*2.4, bh=u*.9*sc;
  tint(0,0,100,cl(70+30*glow,0,100)*AL);
  image(S.grain,cx-bw*.5,cy-bh*.86,bw,bh);
  image(S.grain,cx-bw*.5+bw*.37,cy-bh*.4,bw*.8,bh*.7);
  noTint();
  dc.restore();
}

// ---- ground mist creeping through the ring — a real process, low and slow --
if(act!=='race'){
  dc.globalCompositeOperation='lighter';
  noStroke();
  const NM=Math.round(10+dens*14);
  for(let k=0;k<NM;k++){
    const ph=md(T*.013+fr(k*4.3),1);
    const a2=fr(k*4.3+1)*TAU;
    const mx=cx+Math.cos(a2+T*.021)*rx*(.3+1.25*ph);
    const my=cy+Math.sin(a2)*ry*(.4+.9*ph)+Math.sin(T*.09+k)*ry*.06;
    const rr=u*(.05+.10*fr(k*4.3+2))*(.5+ph)*sc;
    const aa=Math.sin(ph*Math.PI)*(0.030+0.055*glow)*AL;
    if(aa<=.002) continue;
    fill(md(H+180,360),cl(10-6*ph,0,18),cl(56+26*ph,0,96),aa*100);
    ellipse(mx,my,rr*3.0,rr*.82);
  }
  dc.globalCompositeOperation=oldOp;
}

// ---- the sun's own light in the air behind the ring -----------------------
{
  dc.globalCompositeOperation='lighter';
  const sx2=cx+lightX*rx*1.25, sy2=cy+lightY*ry*.9-u*.05*le;
  const rr=u*(.24+.14*le)*sc;
  const hg=dc.createRadialGradient(sx2,sy2,0,sx2,sy2,Math.max(4,rr));
  const ha=(0.05+0.10*glow)*AL;
  const warm=ash?'210,226,255':(bas?'190,210,255':'255,214,158');
  hg.addColorStop(0,'rgba('+warm+','+ha.toFixed(3)+')');
  hg.addColorStop(1,'rgba('+warm+',0)');
  dc.fillStyle=hg; dc.fillRect(sx2-rr,sy2-rr,rr*2,rr*2);
  dc.globalCompositeOperation=oldOp;
}

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0;
noStroke(); noTint();
